// The only place to configure this workflow.
const APP_ID = '';                       // TODO: numeric App Store id, digits only
const COUNTRIES = ['us', 'gb', 'es'];    // storefronts to poll
const CHAT_ID = '';                      // TODO: chat that receives alerts
const SUPABASE_URL = '';                 // TODO: https://<project>.supabase.co
// First run on an existing app: mark the current reviews as seen and alert on none of
// them. Set back to false once the first run has completed.
const BOOTSTRAP = true;

if (!/^\d+$/.test(APP_ID)) throw new Error('APP_ID must be the numeric App Store id');
if (!CHAT_ID) throw new Error('CHAT_ID is not configured in "Config"');
if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');

const base = SUPABASE_URL.replace(/\/+$/, '');

return COUNTRIES.map((country) => ({
  json: {
    country,
    bootstrap: BOOTSTRAP,
    chatId: CHAT_ID,
    storeUrl: base + '/rest/v1/app_reviews',
    feedUrl: 'https://itunes.apple.com/' + country + '/rss/customerreviews/id=' + APP_ID
      + '/sortBy=mostRecent/json',
  },
}));

// Flattens the App Store feeds into review records.
// The feed's first entry is the app itself, not a review: it has no im:rating, which is
// how it is filtered out. Feeds with a single review return an object instead of an
// array, which is the other shape that has to be handled.
const val = (x) => (x && typeof x === 'object' && 'label' in x ? x.label : x);

const reviews = [];
for (const item of $input.all()) {
  const json = item.json || {};
  const country = json.country || (json.$country || 'unknown');
  const raw = json.feed && json.feed.entry;
  if (!raw) continue;
  const entries = Array.isArray(raw) ? raw : [raw];

  for (const e of entries) {
    const rating = parseInt(val(e['im:rating']), 10);
    if (!Number.isInteger(rating)) continue;   // the app metadata entry

    const id = String(val(e.id) || '').trim();
    if (!id) continue;

    reviews.push({
      review_id: country + ':' + id,
      country,
      rating,
      title: String(val(e.title) || '').trim(),
      body: String(val(e.content) || '').replace(/\s+/g, ' ').trim().slice(0, 1500),
      version: String(val(e['im:version']) || '').trim() || null,
      reviewed_at: val(e.updated) ? new Date(val(e.updated)).toISOString() : null,
    });
  }
}

reviews.sort((a, b) => Date.parse(b.reviewed_at || 0) - Date.parse(a.reviewed_at || 0));

const cfg = $('Config').first().json;
return [{
  json: {
    source: 'appstore',
    key_field: 'review_id',
    items: reviews,
    bootstrap: cfg.bootstrap,
    chatId: cfg.chatId,
    storeUrl: cfg.storeUrl,
  },
}];

// One LLM call for the whole batch of new reviews.
const dedup = $input.first().json || {};
const state = $('Normalise reviews').first().json;
const items = Array.isArray(dedup.new_items) ? dedup.new_items : [];

const list = items.map((r) => [
  'id: ' + r.review_id,
  'rating: ' + r.rating + '/5, country: ' + r.country + (r.version ? ', version: ' + r.version : ''),
  'title: ' + r.title,
  'body: ' + r.body,
].join('\n')).join('\n\n---\n\n');

return [{
  json: {
    count: items.length,
    items,
    bootstrap: state.bootstrap,
    chatId: state.chatId,
    storeUrl: state.storeUrl,
    system: 'You triage app store reviews for the developer of the app.',
    user: 'For each review return sentiment, a short lowercase theme, whether it reports a'
      + ' concrete bug, and a suggested_reply drafted for a human to edit and post manually.'
      + ' Keep suggested_reply under 350 characters, no promises about timelines.\n\n' + list,
    max_retries: 2,
    schema: {
      type: 'object',
      required: ['reviews'],
      properties: {
        reviews: {
          type: 'array',
          items: {
            type: 'object',
            required: ['review_id', 'sentiment', 'theme', 'is_bug_report'],
            properties: {
              review_id: { type: 'string' },
              sentiment: { type: 'string', enum: ['positive', 'neutral', 'negative'] },
              theme: { type: 'string' },
              is_bug_report: { type: 'boolean' },
              suggested_reply: { type: 'string' },
            },
          },
        },
      },
    },
  },
}];

// Splits the batch into what gets stored and what gets alerted, and builds the message.
// A review is alerted when it is rated 1 or 2, or when the model called it a bug report.
const llm = $input.first().json || {};
const batch = $('Build review request').first().json;

const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const tagged = llm.ok && llm.data && Array.isArray(llm.data.reviews) ? llm.data.reviews : [];
const byId = new Map(tagged.map((t) => [t.review_id, t]));

const rows = batch.items.map((r) => {
  const t = byId.get(r.review_id) || {};
  const isBug = Boolean(t.is_bug_report);
  const alerted = r.rating <= 2 || isBug;
  return {
    review_id: r.review_id,
    country: r.country,
    rating: r.rating,
    title: r.title,
    body: r.body,
    version: r.version,
    reviewed_at: r.reviewed_at,
    sentiment: t.sentiment || null,
    theme: t.theme || null,
    is_bug: isBug,
    // A draft for a human. Nothing in this workflow sends it anywhere.
    draft_reply: t.suggested_reply || null,
    alerted,
  };
});

// On the first run everything is only recorded, so an existing backlog does not turn
// into a wall of alerts.
const alerts = batch.bootstrap ? [] : rows.filter((r) => r.alerted);

const parts = alerts.length
  ? ['<b>App Store: ' + alerts.length + ' review' + (alerts.length > 1 ? 's' : '') + ' need attention</b>', '']
  : [];
for (const a of alerts) {
  parts.push('<b>' + a.rating + '/5</b> · ' + esc(a.country.toUpperCase())
    + (a.version ? ' · v' + esc(a.version) : '') + (a.is_bug ? ' · <i>bug report</i>' : ''));
  if (a.title) parts.push(esc(a.title));
  parts.push(esc(a.body.slice(0, 300)));
  if (a.theme) parts.push('theme: ' + esc(a.theme));
  parts.push('');
}
if (alerts.length) parts.push('<i>Draft replies are stored, not sent.</i>');

return [{
  json: {
    rows,
    stored: rows.length,
    alertCount: alerts.length,
    bootstrap: batch.bootstrap,
    degraded: !llm.ok,
    chatId: batch.chatId,
    storeUrl: batch.storeUrl,
    text: parts.join('\n').trim(),
  },
}];
